-- Bani's master chart of accounts (Hong Kong restaurants, 90 accounts) is the "F&B — Hong Kong" template that new
-- clients load (platform_load_coa_template, additive only: codes a client already has are skipped). Each master account
-- carries its statement group (Current assets, Fixed assets, …) and whether it is a system account Bani posts to.
-- A client's system accounts are locked: they cannot be deleted, hidden, or change type or side (Bani admins excepted).

ALTER TABLE public.chart_of_accounts ADD COLUMN IF NOT EXISTS is_system boolean NOT NULL DEFAULT false;
ALTER TABLE public.chart_of_accounts ADD COLUMN IF NOT EXISTS statement_group text;

CREATE OR REPLACE FUNCTION public._lock_system_accounts() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
BEGIN
  -- Server jobs (no signed-in user) and Bani admins may change system accounts.
  IF auth.uid() IS NULL OR public.is_platform_admin() THEN RETURN coalesce(NEW, OLD); END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.is_system THEN RAISE EXCEPTION '% is a system account and cannot be deleted', OLD.name; END IF;
    RETURN OLD;
  END IF;
  IF OLD.is_system AND (NEW.account_type IS DISTINCT FROM OLD.account_type OR NEW.normal_side IS DISTINCT FROM OLD.normal_side
                        OR NOT NEW.is_active OR NOT NEW.is_system OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id) THEN
    RAISE EXCEPTION '% is a system account: its type cannot change and it cannot be hidden', OLD.name;
  END IF;
  IF NEW.is_system AND NOT OLD.is_system THEN RAISE EXCEPTION 'Only Bani can mark a system account'; END IF;
  RETURN NEW;
END
$function$;
DROP TRIGGER IF EXISTS chart_of_accounts_lock_system ON public.chart_of_accounts;
CREATE TRIGGER chart_of_accounts_lock_system BEFORE UPDATE OR DELETE ON public.chart_of_accounts
  FOR EACH ROW EXECUTE FUNCTION public._lock_system_accounts();

CREATE OR REPLACE FUNCTION public._insert_system_account_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ BEGIN IF NEW.is_system AND auth.uid() IS NOT NULL AND NOT public.is_platform_admin() THEN NEW.is_system := false; END IF; RETURN NEW; END $function$;
DROP TRIGGER IF EXISTS chart_of_accounts_insert_system ON public.chart_of_accounts;
CREATE TRIGGER chart_of_accounts_insert_system BEFORE INSERT ON public.chart_of_accounts
  FOR EACH ROW EXECUTE FUNCTION public._insert_system_account_guard();
REVOKE ALL ON FUNCTION public._lock_system_accounts() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._insert_system_account_guard() FROM PUBLIC, anon, authenticated;

-- Loading the master also brings its group and system flag.
CREATE OR REPLACE FUNCTION public.platform_load_coa_template(_tenant_id uuid, _template_id uuid)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE _tpl jsonb; _count integer;
BEGIN
  IF NOT public.is_platform_admin(auth.uid()) THEN RAISE EXCEPTION 'not_authorized: platform admin required'; END IF;
  SELECT template INTO _tpl FROM public.coa_templates WHERE id = _template_id AND is_active = true;
  IF _tpl IS NULL THEN RAISE EXCEPTION 'template_not_found'; END IF;
  INSERT INTO public.chart_of_accounts
    (tenant_id, code, name, account_type, normal_side, is_active, is_cash, sort_order, is_system, statement_group)
  SELECT _tenant_id, r->>'code', r->>'name', r->>'account_type', r->>'normal_side',
         true, coalesce((r->>'is_cash')::boolean, false), coalesce((r->>'sort_order')::int, 0),
         coalesce((r->>'is_system')::boolean, false), r->>'group'
  FROM jsonb_array_elements(_tpl) AS r
  ON CONFLICT (tenant_id, code) DO NOTHING;
  GET DIAGNOSTICS _count = ROW_COUNT;
  RETURN _count;
END $$;
REVOKE ALL ON FUNCTION public.platform_load_coa_template(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.platform_load_coa_template(uuid, uuid) TO authenticated;

